/*
    Wheel speed control by the SCADE One model PWM::MotorSystem.

    The model (Scade/MotorSystem_PWM.c, generated, not edited) is a PI speed
    controller followed by a 100-step software PWM. On every SDK timer tick,
    each wheel runs one step of it:

        measured rpm (SDK) --> MotorSystem_PWM() --> motor on/off (SDK)

    so the PWM frequency is ALVIK_TICK_HZ / 100 = 100 Hz.
*/

#include "scade_control.h"
#include "robot_definitions.h"

// Generated by Scade One
#include "MotorSystem_PWM.h"
#include "swan_sensors.h"
#include "swan_consts.h"


// The model reads its PI gains from these globals (sensors kp and ki).
// Values are the Arduino library gains, rescaled from a +-CONTROL_LIMIT output
// to the model's 0..1 duty.
#define KP_DUTY         ((float)MOTOR_KP_DEFAULT / CONTROL_LIMIT)
#define KI_DUTY         ((float)MOTOR_KI_DEFAULT / CONTROL_LIMIT)

// The model integrates T_CYCLE_PWM per step, but steps are 1/ALVIK_TICK_HZ apart.
// Setting T_CYCLE to 0.0001 in the model would make this scale 1.
#define KI_TICK_SCALE   ((1.0f / ALVIK_TICK_HZ) / T_CYCLE_PWM)

swan_float32 kp_PWM = KP_DUTY;
swan_float32 ki_PWM = KI_DUTY * KI_TICK_SCALE;

// Model state (integrator, PWM counter), one instance per wheel
static outC_MotorSystem_PWM wheel[MOTOR_COUNT];
static volatile swan_float32 target_rpm[MOTOR_COUNT];


void scade_control_init(void){
    for (int m = 0; m < MOTOR_COUNT; m++){
        MotorSystem_init_PWM(&wheel[m]);
        target_rpm[m] = 0.0f;
    }
}

void scade_control_set_rpm(motor_id_t motor, float rpm){
    if (motor >= MOTOR_COUNT){
        return;
    }
    // The model clamps its duty to 0..1, so it only drives forward
    target_rpm[motor] = (rpm > 0.0f) ? rpm : 0.0f;
}

float scade_control_get_target(motor_id_t motor){
    if (motor >= MOTOR_COUNT){
        return 0.0f;
    }
    return target_rpm[motor];
}

void scade_control_step(void){
    for (int m = 0; m < MOTOR_COUNT; m++){
        swan_bool on;
        MotorSystem_PWM(target_rpm[m], motor_get_rpm((motor_id_t)m), &on, &wheel[m]);
        motor_set((motor_id_t)m, on);
    }
}
